alter table public.mandante_entregas add column if not exists version integer not null default 1 check(version>0),add column if not exists entrega_raiz_id uuid references public.mandante_entregas(id) on delete restrict,add column if not exists entrega_anterior_id uuid references public.mandante_entregas(id) on delete restrict,add column if not exists respondido_por text,add column if not exists respondido_at timestamptz;
update public.mandante_entregas set entrega_raiz_id=id where entrega_raiz_id is null;
alter table public.mandante_entregas alter column entrega_raiz_id set not null;
create unique index if not exists mandante_entregas_raiz_version_uidx on public.mandante_entregas(entrega_raiz_id,version);
create table if not exists public.mandante_entrega_acciones(id uuid primary key default gen_random_uuid(),entrega_id uuid not null references public.mandante_entregas(id) on delete restrict,contrato_id uuid not null references public.mandante_contratos(id) on delete restrict,empresa_mandante text not null,accion text not null,estado_resultante text,comentario text,actor_nombre text,actor_rut text,actor_cargo text,actor_empresa text,actor_tipo text not null default 'Usuario Obraxis',created_at timestamptz not null default now());
alter table public.mandante_entrega_acciones enable row level security;
grant select,insert on public.mandante_entrega_acciones to authenticated;
create policy mandante_entrega_acciones_empresas on public.mandante_entrega_acciones for select to authenticated using(exists(select 1 from public.mandante_contratos c where c.id=contrato_id and((select private.usuario_puede_empresa(c.empresa_mandante))or(c.empresa_obraxis_vinculada is not null and(select private.usuario_puede_empresa(c.empresa_obraxis_vinculada))))));
create policy mandante_entrega_acciones_insert on public.mandante_entrega_acciones for insert to authenticated with check(exists(select 1 from public.mandante_contratos c where c.id=contrato_id and((select private.usuario_puede_empresa(c.empresa_mandante))or(c.empresa_obraxis_vinculada is not null and(select private.usuario_puede_empresa(c.empresa_obraxis_vinculada))))));
create or replace function public.inicializar_raiz_entrega_mandante() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.entrega_raiz_id is null then new.entrega_raiz_id:=new.id;end if;return new;end;$$;
drop trigger if exists trg_inicializar_raiz_entrega_mandante on public.mandante_entregas;
create trigger trg_inicializar_raiz_entrega_mandante before insert on public.mandante_entregas for each row execute function public.inicializar_raiz_entrega_mandante();
create index if not exists mandante_entrega_acciones_entrega_idx on public.mandante_entrega_acciones(entrega_id,created_at);;
